questionvariables.text:
cardn(S) := length(listify(S));
dset(S) := if emptyp(S) then "\\{\\,\\}" else sconcat("\\{", simplode(map(string, listify(S)), ", "), "\\}");
ix: 1+rand(10);
/* Design: list the elements of a described set and give n(A). Source: adapted from SMP Book 1, Chapter 2, Exercise A, question 1.
   Curated list, one seed per entry: [description TeX, description words, A, first non-member above max(A), explanation, n(A), n(A)-1, n(A)+2, max(A)].
   Counts are literals: test inputs are evaluated with simp:false, which leaves cardn() unevaluated. */
L: [["\\{\\text{the factors of 75}\\}","the factors of 75",{1,3,5,15,25,75},76,"The factors of \\(75\\) come in pairs: \\(1 \\times 75\\), \\(3 \\times 25\\), \\(5 \\times 15\\).",6,5,8,75],["\\{\\text{the multiples of 6 between 40 and 70}\\}","the multiples of 6 between 40 and 70",{42,48,54,60,66},67,"The first multiple of \\(6\\) above \\(40\\) is \\(42\\) and the last below \\(70\\) is \\(66\\).",5,4,7,66],["\\{\\text{the prime numbers between 30 and 60}\\}","the prime numbers between 30 and 60",{31,37,41,43,47,53,59},60,"Test each odd number from \\(31\\) to \\(59\\): \\(33\\), \\(35\\), \\(39\\), \\(45\\), \\(49\\), \\(51\\), \\(55\\) and \\(57\\) have other factors, so they are not prime.",7,6,9,59],["\\{\\text{the factors of 45}\\}","the factors of 45",{1,3,5,9,15,45},46,"The factors of \\(45\\) come in pairs: \\(1 \\times 45\\), \\(3 \\times 15\\), \\(5 \\times 9\\).",6,5,8,45],["\\{\\text{the square numbers between 10 and 90}\\}","the square numbers between 10 and 90",{16,25,36,49,64,81},82,"\\(3^2 = 9\\) is too small and \\(10^2 = 100\\) is too big, so the squares are \\(4^2\\) to \\(9^2\\).",6,5,8,81],["\\{\\text{the multiples of 8 between 50 and 100}\\}","the multiples of 8 between 50 and 100",{56,64,72,80,88,96},97,"The first multiple of \\(8\\) above \\(50\\) is \\(56\\) and the last below \\(100\\) is \\(96\\).",6,5,8,96],["\\{\\text{the factors of 28}\\}","the factors of 28",{1,2,4,7,14,28},29,"The factors of \\(28\\) come in pairs: \\(1 \\times 28\\), \\(2 \\times 14\\), \\(4 \\times 7\\).",6,5,8,28],["\\{\\text{the prime numbers between 60 and 90}\\}","the prime numbers between 60 and 90",{61,67,71,73,79,83,89},90,"Test each odd number from \\(61\\) to \\(89\\): \\(63\\), \\(65\\), \\(69\\), \\(75\\), \\(77\\), \\(81\\), \\(85\\) and \\(87\\) have other factors, so they are not prime.",7,6,9,89],["\\{\\text{the odd multiples of 5 between 20 and 80}\\}","the odd multiples of 5 between 20 and 80",{25,35,45,55,65,75},76,"The odd multiples of \\(5\\) end in \\(5\\): from \\(25\\) up to \\(75\\).",6,5,8,75],["\\{\\text{the cube numbers between 5 and 300}\\}","the cube numbers between 5 and 300",{8,27,64,125,216},217,"\\(1^3 = 1\\) is too small and \\(7^3 = 343\\) is too big, so the cubes are \\(2^3\\) to \\(6^3\\).",5,4,7,216]];
Ad: L[ix][1]; dw: L[ix][2]; A: L[ix][3]; y1: L[ix][4]; expl: L[ix][5];
nA: L[ix][6]; x1: L[ix][9];
/* test values */
t2a: setdifference(A,{x1}); t2b: L[ix][7]; t3a: union(A,{y1}); t3b: L[ix][8]; t4a: union(setdifference(A,{x1}),{y1});
